update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/types-de-maintenance/maintenance-predictive/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance prédictive","mecanisme":"Surveiller l''état de santé réel de chaque machine, analyser les données, intervenir avant la panne. Cette page donne la chaîne complète, de la sonde à la décision. Puis elle traite le point que les éditeurs évitent : qui exécute les travaux annoncés.","cta":"Lancer mon diagnostic gratuit","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"La vibration","libelle":"la signature la plus riche","detail":"Balourd, défaut d''alignement, bague de roulement piquée, engrenage usé."},{"valeur":"La température","libelle":"un échauffement anormal précède presque toujours la casse","detail":"La thermographie infrarouge révèle aussi les défauts électriques."},{"valeur":"Le courant et la consommation","libelle":"la signature électrique d''un moteur trahit son usure mécanique sans le démonter."},{"valeur":"La pression et le débit","libelle":"sur un circuit hydraulique ou pneumatique, la dérive annonce la fuite ou l''encrassement."},{"valeur":"L''analyse d''huile","libelle":"particules métalliques, viscosité, contamination","detail":"Un indicateur d''usure interne redoutablement fiable."},{"valeur":"L''ultrason","libelle":"les fuites d''air comprimé, première source d''économie d''énergie dans beaucoup d''usines."},{"valeur":"Pas une boule de cristal.","libelle":"Un modèle donne une probabilité et une fenêtre, jamais une date certaine."},{"valeur":"Pas réservé aux grandes usines.","libelle":"Cinq machines critiques instrumentées produisent déjà un effet."},{"valeur":"Pas la fin du préventif.","libelle":"Les deux coexistent : l''un couvre le parc courant, l''autre les actifs critiques."},{"valeur":"Toutes les pannes ne se prédisent pas.","libelle":"Une casse par corps étranger, une erreur de conduite, un défaut de pièce neuve échappent à tout modèle."},{"valeur":"Le coût d''entrée existe.","libelle":"Capteurs, réseau, plateforme, temps interne : sur un parc peu critique, le calcul ne passe pas."},{"valeur":"La compétence d''interprétation est rare","libelle":", et un système de surveillance négligé se périme vite","detail":"Sonde décalée, seuil jamais révisé, et la confiance s''effondre."},{"valeur":"10 %","libelle":"des candidats retenus, l''interprétation d''un relevé est un métier qui s''évalue"},{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers"},{"valeur":"0","libelle":"capteur ou logiciel vendu par Migen","detail":"Nous ne sommes ni éditeur ni fabricant"}],"reponse":[{"texte":"Le raccourci utile : la conditionnelle dit « la température est trop haute », la prédictive dit « à ce rythme, le palier lâche dans trois semaines »."}]}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-predictive/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"probleme","punchline":"Le roulement sifflait depuis trois semaines. La donnée existait déjà. Personne n''était payé pour la regarder.","puces":[{"accroche":"La donnée dort dans vos automates.","texte":"Variateurs, compteurs d''énergie, codes défaut récurrents : l''information est là, inexploitée, et on vous vend des capteurs avant de vous avoir demandé ce qui casse."},{"accroche":"L''alerte ne débouche sur rien.","texte":"Un signalement qui ne crée pas d''ordre de travail est un signalement mort. La boucle se ferme sur le terrain, pas sur un écran."},{"accroche":"Le projet pilote ne finit jamais.","texte":"Trop grand, trop vite, sans pilote nommé, il ne survit pas à la première réorganisation."},{"accroche":"Et surtout : personne pour exécuter.","texte":"Aucun éditeur n''enverra un technicien à 6h du matin reprendre l''accouplement que son système vient de signaler."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"L''audit de vos installations","texte":"une demi-journée sur site suffit à dire quelles machines méritent une surveillance et lesquelles n''en ont pas besoin."},"benefice":"Vous savez où investir avant d''acheter quoi que ce soit. Livrable : une liste priorisée."},{"prestation":{"accroche":"L''inventaire de la donnée existante","texte":"automates, variateurs, compteurs, GMAO. On complète, on ne remplace pas."},"benefice":"L''investissement initial tombe, parce qu''une grande partie de l''information est déjà collectée."},{"prestation":{"accroche":"L''aide au choix des outils","texte":"instrumentation, réseau, logiciel, hébergement local ou cloud, comparés avec vous."},"benefice":"Un conseil sans intérêt commercial dans le résultat, puisque nous ne vendons ni l''un ni l''autre."},{"prestation":{"accroche":"Les inspections périodiques","texte":"analyse vibratoire, thermographie infrarouge, ultrason, contrôle d''huile. Nos techniciens passent, relèvent, interprètent."},"benefice":"Vous obtenez la compétence d''interprétation sans avoir à la recruter sur un marché tendu."},{"prestation":{"accroche":"L''exécution des travaux annoncés par le modèle","texte":"remplacement de roulement, réalignement, reprise de connexion, remise en état hydraulique."},"benefice":"La prédiction devient une machine réparée, pas une ligne dans un tableau de bord."},{"prestation":{"accroche":"L''intégration dans votre GMAO","texte":"chaque signalement crée une demande d''intervention dans votre outil, pas dans un outil parallèle."},"benefice":"Pas de double saisie, et les indicateurs sortent d''une source unique."}],"prose":[{"texte":"Pour industrialiser la démarche avec des visites planifiées et une priorité d''intervention, voir le [contrat de maintenance Zéro arrêt](/offres/zero-arret/). Pour une panne en cours, voir le [dépannage industriel](/offres/depannage-industriel/). Migen est une [entreprise de maintenance industrielle](/offres/) présente partout en France."}]}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-predictive/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Choisir le périmètre.","texte":"Cinq à dix équipements critiques, pas davantage. Le critère est ce que coûte une heure d''arrêt, pas l''âge de la machine."},{"titre":"Inventorier la donnée existante.","texte":"Automates, variateurs, compteurs, historique GMAO. Une grande partie de l''information est déjà là."},{"titre":"Instrumenter ce qui manque.","texte":"Capteurs fixes sur les actifs critiques, tournée portable ailleurs. On complète le dispositif, on ne le refait pas."},{"titre":"Établir la référence.","texte":"Plusieurs semaines de fonctionnement normal sont nécessaires pour que le modèle apprenne le comportement sain. Un modèle appris sur une machine déjà dégradée apprend la dégradation comme normale."},{"titre":"Déclencher, tester, corriger.","texte":"Les premiers signalements sont toujours trop nombreux. Le réglage des seuils est un travail d''ajustement continu, mené avec vos techniciens."},{"titre":"Industrialiser.","texte":"Une fois la méthode prouvée sur le premier périmètre, l''extension devient un exercice de logistique."}]},{"type":"garanties","puces":[{"accroche":"La donnée reste votre propriété.","texte":"Nous travaillons dans votre environnement, selon vos règles d''accès, que l''hébergement soit local ou dans le cloud. Vos exigences qualité et vos clauses de confidentialité sont les nôtres."},{"accroche":"L''indépendance du conseil.","texte":"Nous ne vendons ni capteur ni logiciel. Quand nous vous disons qu''une machine ne mérite pas d''être instrumentée, cela ne nous coûte rien de le dire."},{"accroche":"L''exécution derrière l''alerte.","texte":"Nos techniciens réalisent les travaux que le modèle annonce, avec les habilitations exigées par votre installation, vérifiées avant le déplacement."}]},{"type":"cta","question":"Besoin de savoir quelles machines méritent d''être instrumentées, et lesquelles n''en ont pas besoin ?","bouton":"Lancer mon diagnostic gratuit","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Maintenance préventive et curative d''une fonderie et d''un usinage, automobile","texte":"tenue 7 jours sur 7, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Maintien d''un parc machines, équipementier automobile","texte":"un technicien de maintenance dédié, intégré aux équipes du site en 2025","lienLibelle":"Étude de cas AUTOLIV : maintien d''un site","lienHref":"/preuves/autoliv/"},{"titre":"Maintenance des installations sécurisée par des techniciens intégrés, équipementier automobile","texte":"dispositif en place en 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Deux techniciens intégrés en 3x8 sur les lignes liquides et poudre, agroalimentaire","texte":"site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Maintenance des centres d''usinage, presses et machines à commande numérique, automobile","texte":"un technicien à temps plein","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Un automaticien SIEMENS en renfort sur le démarrage d''une nouvelle ligne, industrie","texte":"près de Lyon, en 2025","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"}]}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-predictive/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Combien ça coûte, et au bout de combien de temps c''est rentable ?","reponse":"Le chiffrage se fait sur devis, machine par machine. Le retour se calcule sur l''heure d''arrêt évitée, pas sur la taille de l''entreprise. Comptez quelques semaines pour établir la référence, puis quelques mois pour ajuster les seuils avant les premiers signalements utiles."},{"question":"Faut-il de l''intelligence artificielle pour commencer ?","reponse":"Non. Un seuil bien réglé sur une sonde de température évite déjà des pannes. L''apprentissage automatique apporte un gain réel sur les machines complexes ou nombreuses, quand l''historique est suffisant. Une intelligence artificielle mal nourrie produit de faux signalements, et la confiance s''effondre."},{"question":"Migen vend-il des capteurs ou des logiciels ?","reponse":"Non, et c''est volontaire. Nous sommes un prestataire de services. Nous vous aidons à choisir les outils, nous les exploitons avec vos équipes, et nous fournissons les techniciens qui interviennent sur les alertes."},{"question":"Est-ce adapté à une PME ?","reponse":"Oui, à condition de cibler. Trois machines critiques bien suivies valent mieux qu''un programme global inabouti. Le calcul se fait sur ce que coûte une heure d''immobilisation de ces trois machines, rien d''autre."},{"question":"Comment l''intégrer à notre GMAO existante ?","reponse":"L''objectif est qu''une détection d''anomalie crée directement une demande d''intervention dans votre outil, sans double saisie. La plupart des solutions du marché proposent une interface d''échange, et nous branchons la boucle avec votre service informatique."},{"question":"Que devient la donnée collectée sur nos machines ?","reponse":"Elle reste votre propriété. Nous travaillons dans votre environnement, selon vos règles d''accès, que l''hébergement soit dans le cloud ou sur vos serveurs locaux. Ce point se traite au contrat, pas après."}]},{"type":"ctaFinal","question":"Besoin de quelqu''un qui regarde les courbes le lundi matin, et qui répare le mardi ?","bouton":"Lancer mon diagnostic gratuit","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-predictive/';
